import { TreeView, type TreeNode } from "@/components/tree-view";

const [nodes, setNodes] = useState<TreeNode[]>([
  { id: "docs", parent: null, title: "Docs" },
  { id: "intro", parent: "docs", title: "Introduction" },
  { id: "readme", parent: null, title: "README.md", leaf: true },
]);

<TreeView nodes={nodes} onNodesChange={setNodes} defaultExpanded={["docs"]} onSelect={(n) => router.push(`/p/${n.id}`)} />
